def footer():
 return '<footer class="site-footer"><div class="footer-grid"><div class="footer-brand"><a class="brand brand-logo" href="/" aria-label="Brazil Migration ana sayfa"><img src="/brazil-migration-logo.png" alt="Brazil Migration" width="2048" height="683"></a><p>Brezilya’da yaşam, aile ve iş planlarınız için Türkçe danışmanlık. São Paulo odaklı, adım adım destek.</p><span class="footer-location">São Paulo · Brezilya</span></div><div><h2>Hizmetlerimiz</h2>'+''.join('<a href="/'+p['slug']+'/">'+e(p['name'])+'</a>' for p in PAGES)+'</div><div><h2>Yolculuğunuzu planlayın</h2><a href="/degerlendirme/">Ön değerlendirme</a><a href="/#yaklasim">Danışmanlık yaklaşımımız</a><a href="/giris/">Danışan girişi</a><a href="/partner/">Partner Girişi</a><a href="/iletisim/">İletişim</a></div><div class="footer-contact"><h2>İlk adımı birlikte atalım</h2><p>Hedefinizi anlatın, ihtiyaç duyduğunuz hizmeti birlikte belirleyelim.</p><a class="btn" href="/iletisim/">15 dakikalık ücretsiz görüşme ↗</a></div></div><div class="footer-bottom"><span>© 2026 Brazil Migration</span><a href="/kaynaklar/">Bilgilendirme ve görsel kaynakları</a><a href="#main">Sayfanın başına dön ↑</a></div><p class="legal">'+WARN+'</p></footer><dialog id="booking"><button class="close" onclick="closeBooking()" aria-label="Kapat">×</button><div id="booking-body"></div></dialog><script src="/app.js" defer></script>'
def why():return '<section class="why" id="yaklasim"><div class="wrap"><div class="kicker">NEDEN BİZİ SEÇMELİSİNİZ?</div><h2>São Paulo’yu merkeze alan,<br>sizi dinleyen bir yaklaşım.</h2><div class="why-grid"><article><span>01</span><h3>Yerel yaşama odak</h3><p>Belge hazırlığını konut, ulaşım ve günlük yaşam ihtiyaçlarınızla birlikte düşünün.</p></article><article><span>02</span><h3>Açık kapsam</h3><p>Hizmet bedeli, dış giderler ve resmî makam kararları arasındaki farkı başlangıçta görün.</p></article><article><span>03</span><h3>Daha az kâğıt</h3><p>Dijital dosya düzeni ve çevrim içi görüşmelerle gereksiz çıktı ve yolculuk ihtiyacını azaltmayı hedefliyoruz.</p></article></div></div></section>'
def cta():return ''
def head(title,meta,path,schema=None):
 return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#1B5E20"><title>'+e(title)+'</title><meta name="description" content="'+e(meta,quote=True)+'"><link rel="canonical" href="'+BASE+path+'"><meta property="og:title" content="'+e(title,quote=True)+'"><meta property="og:description" content="'+e(meta,quote=True)+'"><meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta property="og:url" content="'+BASE+path+'"><meta property="og:image" content="'+BASE+'/sao-paulo-day-hq.png"><script src="/theme.js"></script><link rel="stylesheet" href="/style.css?v=11">'+('<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</', r'<\/')+'</script>' if schema else '')+'</head>'
def save(path,title,meta,body,kind='home',schema=None):
 if kind=='home':body=body.replace('<section class="why"',map_section()+'<section class="why"',1)
 body=body.replace('<section class="cta wrap">','<section class="cta wrap" id="gorusme">',1)
 out=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html'
 out.parent.mkdir(parents=True,exist_ok=True)
 out.write_text(head(title,meta,path,schema)+f'<body data-page="{kind}">'+header()+'<main id="main">'+body+'</main>'+footer()+'</body></html>')
def article(p):return '<section class="wrap reading" id="rehber"><aside><div class="kicker">2026 REHBERİ</div><h2>Doğru bilgi.<br>Net adımlar.</h2><p>São Paulo odaklı<br>Türkçe danışmanlık içeriği</p><a href="#paketler">Paketlere geç ↓</a></aside><div>'+''.join(f'<article><h2>{e(h)}</h2><p>{cite(s)}</p></article>' for h,s in p['article'])+'</div></section>'
def package_section(p):
 x='<section class="packages-section wrap" id="paketler"><div class="section-head"><div><div class="kicker">KAPSAMI BELLİ DANIŞMANLIK</div><h2>Size uygun desteği seçin.</h2></div><span class="pill">Fiyatlar USD cinsindedir</span></div>'
 x+='<div class="package-grid" style="--cols:'+str(len(p['packs']))+'">'
 for i,k in enumerate(p['packs']):
  x+=f'<article class="package {"featured" if i==1 else ""}"><div class="kicker">{i+1:02d} / {e(p["name"])}</div><h3>{e(k["name"])}</h3><div class="price" data-base="{k["price"]}">{k["price"]:,.0f} <small>USD</small></div><p class="who">{e(k["who"])}</p><ul>'+''.join(f'<li>{e(s)}</li>' for s in k['scope'][:5])+f'</ul><a class="btn {"lime" if i==1 else "outline"}" href="#paket-{i}">Paketi İncele <span>↓</span></a></article>'
 x+='</div><p class="caption">Paketler bir ana başvuru sahibi / bir şirket içindir. Harçlar, noter, apostil, tercüme, seyahat, sermaye ve üçüncü taraf giderleri dahil değildir. Hizmet kapsamı sözleşmede kesinleşir.</p><div class="package-details">'
 for i,k in enumerate(p['packs']):
  x+=f'<details id="paket-{i}" class="package-detail"><summary><span>{e(k["name"])}</span><span>{k["price"]:,.0f} USD · Ayrıntılar</span></summary><div class="table-scroll"><table><caption>{e(k["name"])} — ayrıntılı hizmet tablosu</caption><tbody>'
  rows=[('Kapsam neleri içerir?','<ul>'+''.join('<li>'+e(s)+'</li>' for s in k['scope'])+'</ul>'),('Kimler için uygundur?',e(k['who'])),('Süreç adımları','<ol>'+''.join('<li>'+e(s)+'</li>' for s in k['steps'])+'</ol>'),('Gerekli belgeler',e(k['docs'])),('Avantajlar',e(k['benefit'])),('Hizmet bedeli',f'{k["price"]:,.0f} USD.') ]
  x+=''.join(f'<tr><th scope="row">{a}</th><td>{b}</td></tr>' for a,b in rows)+'</tbody></table></div>'+btn('Bu paket için 15 dakikalık görüşme','',f'onclick="book(\'{p["id"]}\',{i})"')+'</details>'
 x+='</div>'
 if p['id']=='sirket':
  rows=[('Banka hesabı','Başvuru dosyası ve banka koordinasyonu; kabul bankaya aittir.','İşletme / Premium'),('Muhasebe','İşletme: 3 ay / 30 belge; Premium: 6 ay / 50 belge. Bordro ve dış ticaret hariç temel kapsam.','Paket sonrası aylık teklif'),('Web sitesi','5 kurumsal sayfa, 1 dil, mobil uyum ve temel SEO. Domain, hosting ve e-ticaret hariç.','Premium; diğerlerine ek teklif'),('Kurumsal kimlik','Logo düzeni, renk/font rehberi, kartvizit dosyası.','Premium'),('Ofis bulma','5 veya 8 seçenek; Premium’da 2 uzaktan görüşme. Kira ve depozito hariç.','İşletme / Premium'),('İhracat Ar-Ge','Bir sektör / bir hedef pazar için masa başı ön araştırma; satış garantisi yok.','Premium'),('Aylık destek','İşletme 3, Premium 6 aylık görüşme; devamı ayrı teklif.','İşletme / Premium'),('Yatırımcı oturumu','Ayrı göçmenlik dosyası; Premium’da yalnızca ilk ihtiyaç analizi.','Başvuru ayrıca fiyatlanır')]
  x+='<h3 class="subheading">Operasyon ve ek hizmetler</h3><div class="table-scroll"><table><thead><tr><th>Hizmet</th><th>Tanımlı kapsam</th><th>Dahil olma durumu</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
 return x+'</section>'
def docs(p):
 conditional={'oturum':{3,5},'lgbt':{3},'evlilik':{1,2,4},'vatandaslik':{8,9,10},'sirket':{2,5,6}}
 cards=''
 for i,(h,description) in enumerate(p['docs']):
  required=i not in conditional[p['id']]
  cards+=f'<div class="doc-item" data-required="{str(required).lower()}"><label class="doc"><input class="doc-ready" type="checkbox" onchange="updateDocs()"><span><strong>{e(h)}</strong><small>{e(description)}</small></span></label><span class="doc-required">{"Bu dosyada zorunlu" if required else "Duruma göre gerekli"}</span></div>'
 return '<section class="documents wrap" id="belgeler"><div class="section-head"><div><div class="kicker">DOSYANIZI HAZIRLAYIN</div><h2>Belge kontrol listesi.</h2></div></div><div class="document-score" aria-live="polite"><div><span>Belge hazırlık skoru</span><strong class="doc-score">%0</strong></div><progress class="doc-meter" max="100" value="0" aria-label="Belge hazırlık yüzdesi"></progress><b class="doc-status">Belgelerinizi işaretleyin</b><span class="doc-progress"></span></div><p class="caption">Hazır olan belgelerinizi işaretleyin. Zorunlu ve koşula bağlı kalemler listede belirtilmiştir; dosyanızın kesin belge kapsamı danışman incelemesiyle netleşir. Skor yalnızca zorunlu kalemlerin hazırlığını ölçer; hukuki uygunluk veya resmî onay değildir. Seçimler bu sayfa açıkken tutulur.</p><div class="doc-grid">'+cards+'</div><p class="caption">'+cite('Belge dayanağı: '+('[natdocs] [623] [nat] [lang]' if p['id']=='vatandaslik' else '[manual] [rn]' if p['id']=='sirket' else '[pf] [union]'))+'</p></section>'
def faq(p):return '<section class="faq wrap" id="sss"><div><div class="kicker">MERAK EDİLENLER</div><h2>Sorularınıza<br>açık yanıtlar.</h2><p>'+e(p['name'])+' hakkında sıkça sorulanlar.</p></div><div>'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in p['faqs'])+'</div></section>'
