 schema={'@context':'https://schema.org','@graph':[{'@type':'WebPage','name':p['seo'],'description':p['meta'],'url':BASE+path,'inLanguage':'tr','dateModified':'2026-10-19'},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Ana sayfa','item':BASE+'/'},{'@type':'ListItem','position':2,'name':p['name'],'item':BASE+path}]},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faqs']]}]}
